<?php
require_once 'config/database.php';require_once 'includes/auth.php';require_once 'includes/functions.php';require_login();$uid=current_user()['user_id'];
$teach=$pdo->prepare("SELECT s.skill_name FROM UserSkills us JOIN Skills s ON s.skill_id=us.skill_id WHERE us.user_id=? AND us.skill_type='teach' LIMIT 5");$teach->execute([$uid]);$teach=$teach->fetchAll();
$learn=$pdo->prepare("SELECT s.skill_name FROM UserSkills us JOIN Skills s ON s.skill_id=us.skill_id WHERE us.user_id=? AND us.skill_type='learn' LIMIT 5");$learn->execute([$uid]);$learn=$learn->fetchAll();
$pending=$pdo->prepare("SELECT COUNT(*) FROM SkillRequests WHERE receiver_id=? AND status='pending'");$pending->execute([$uid]);$pending=(int)$pending->fetchColumn();
$up=$pdo->prepare("SELECT ls.*,s.skill_name,u.first_name,u.last_name FROM LearningSessions ls JOIN Skills s ON s.skill_id=ls.skill_id JOIN Users u ON u.user_id=CASE WHEN ls.teacher_id=? THEN ls.learner_id ELSE ls.teacher_id END WHERE (ls.teacher_id=? OR ls.learner_id=?) AND ls.status='scheduled' ORDER BY session_date,start_time LIMIT 4");$up->execute([$uid,$uid,$uid]);$up=$up->fetchAll();
$msg=$pdo->prepare("SELECT COUNT(*) FROM Messages WHERE receiver_id=? AND is_read=0");$msg->execute([$uid]);$msg=(int)$msg->fetchColumn();
$matches = find_matches($pdo, $uid, 3);
$title='Dashboard';include 'includes/header.php';
?>
<div class="dashboard-head"><div><div class="eyebrow">YOUR WORKSPACE</div><h1>Good to see you, <?=e(current_user()['first_name'])?>.</h1><p class="muted">Your next swap is closer than you think.</p></div><div class="actions"><a class="btn" href="add-skill.php">+ Add a skill</a><a class="btn ghost" href="matches.php">Find matches</a></div></div>
<div class="stats-grid"><div class="stat-card"><span>Skills I teach</span><b><?=count($teach)?></b></div><div class="stat-card"><span>Skills I learn</span><b><?=count($learn)?></b></div><div class="stat-card"><span>Pending requests</span><b><?=$pending?></b></div><div class="stat-card"><span>Unread messages</span><b><?=$msg?></b></div><div class="stat-card"><span>Rating</span><b><?=number_format(avg_rating($pdo,$uid),1)?>★</b></div></div>
<div class="dash-grid"><section><div class="card"><div class="section-head"><h2>My skills</h2><a href="my-skills.php">Manage →</a></div><div class="skill-columns"><div><small>I TEACH</small><div class="tags"><?php foreach($teach as $x):?><span class="tag teach"><?=e($x['skill_name'])?></span><?php endforeach;?></div></div><div><small>I WANT TO LEARN</small><div class="tags"><?php foreach($learn as $x):?><span class="tag learn"><?=e($x['skill_name'])?></span><?php endforeach;?></div></div></div></div>
<div class="card"><div class="section-head"><h2>Suggested matches</h2><a href="matches.php">See all →</a></div><?php if(!$matches):?><div class="empty">No live matches yet. Add both teach and learn skills to unlock matching.</div><?php endif;?><?php foreach($matches as $m):?><a class="match-row" href="profile.php?id=<?=$m['other_id']?>"><div class="avatar"><?=e(initials($m['first_name'],$m['last_name']))?></div><div><b><?=e($m['first_name'].' '.$m['last_name'])?></b><p><?=e($m['they_can_teach']??'Skill')?> ↔ <?=e($m['i_can_teach']??'Skill')?></p></div><strong><?=number_format((float)$m['compatibility_score'],0)?>%</strong></a><?php endforeach;?></div></section>
<aside><div class="card"><div class="section-head"><h2>Upcoming</h2><a href="sessions.php">All →</a></div><?php foreach($up as $x):?><div class="mini-item"><b><?=e($x['session_title'])?></b><span><?=e($x['session_date'])?> · <?=substr($x['start_time'],0,5)?></span></div><?php endforeach;?></div><div class="card"><h3>Quick actions</h3><div class="quick"><a href="requests.php">↔ Requests</a><a href="messages.php">✉ Messages</a><a href="achievements.php">✦ Achievements</a><a href="reviews.php">★ Reviews</a></div></div></aside></div>
